    for i = 2, #xs do
      local v = krt.as_flint(xs[i])
      if want_max then
        if v > m then m = v end
      else
        if v < m then m = v end
      end
    end
    return m
  end
  if count == 0 then krt.fail("VALUE_ERROR", "min/max needs a value") end
  m = krt.as_flint(args[1])
  for i = 2, count do
    local v = krt.as_flint(args[i])
    if want_max then
      if v > m then m = v end
    else
      if v < m then m = v end
    end
  end
  return m
end

