T (st[err] is NONE):", "                    return stmts", "                if e[k] == \"self_init\":", "                    dict sctx = st[model_ctx]", "                    if sctx is NONE OR NOT sctx[in_construct]:", "                        fail(st, e, \"SCOPE_ERROR\", \"self(...) in construct\", \"self(...) outside construct\")", "                        return stmts", "                    if st[block_depth] != sctx[level] OR len(stmts) != 0:", "                        fail(st, e, \"SYNTAX_ERROR\", \"self(...) as the first statement of construct\", \"nested or later self(...)\")", "                        return stmts", "                    if sctx[self_seen]:", "                        fail(st, e, \"REDECLARE_ERROR\", \"one self(...) per construct\", \"second self(...)\")", "                        return stmts", "                    list sargs = e[names]", "                    dict ssch = sctx[schema]", "                    dict scons = ssch[ctor]", "                    list sps = []", "                    if NOT (scons is NONE):", "                        sps = scons[params]", "                    flint slast = -1", "                    list sfields = []", "                    flint si = 0", "                    while si < len(sargs):", "                        dict sat = sargs[si]", "                        str san = sat[value]", "                        flint sfound = -1", "                        flint sj = 0", "                        while sj < len(sps):", "                            dict ssp = sps[sj]", "                            if ssp[name] == san:", "                                sfound = sj", "                            sj += 1", "                        if sfound < 0:", "                            fail(st, sat, \"NAME_ERROR\", \"construct parameter in self(...)\", cat([\"unknown '\", san, \"'\"]))", "                            return stmts", "                        if sfound <= slast:", "                            fail(st, sat, \"SYNTAX_E